import { sql } from "drizzle-orm";
import { customType, timestamp, uuid } from "drizzle-orm/pg-core";

/** Primary key: UUID v7 (SPEC 10), generated by PostgreSQL 18's built-in uuidv7(). */
export const id = () => uuid("id").primaryKey().default(sql`uuidv7()`);

/** created_at / updated_at on every table (SPEC 10). Times are UTC. */
export const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};

/**
 * PostGIS MultiPolygon in WGS 84. Written as GeoJSON through ST_GeomFromGeoJSON in the import,
 * and read only through registered queries (never selected as raw geometry by the app).
 */
export const multiPolygon = customType<{ data: string; driverData: string }>({
  dataType: () => "geometry(MultiPolygon, 4326)",
});
